import {useEffect,useMemo,useState} from 'react';
import {CheckCircle2,CircleAlert,ClipboardList,History} from 'lucide-react';
import {getNutritionAssessment,saveNutritionAssessment,transitionNutritionAssessment} from '../../lib/practiceOperationsApi';

const EMPTY={dietary_preference:'',allergies_intolerances:[],food_restrictions:[],meal_timing_frequency:'',typical_dietary_intake:'',appetite_eating_patterns:'',water_intake:'',food_dislikes_preferences:'',nutrition_medical_conditions:[],relevant_medications:[],relevant_supplements:[],weight_management_goals:[],recovery_disease_management_goals:[],consultant_notes:''};
const list=value=>Array.isArray(value)?value.filter(Boolean):value?[value]:[];
const split=value=>String(value||'').split(',').map(item=>item.trim()).filter(Boolean);
const label=value=>String(value||'').replaceAll('_',' ').toLowerCase().replace(/^./,letter=>letter.toUpperCase());
const fieldClass='mt-2 min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm text-slate-950 focus:border-blue-600 focus:outline-none focus:ring-2 focus:ring-blue-100';

function buildSources(data,measurements,biomarkers){
  const sections=data?.sections||{};const sources=[];const push=(source_type,source_id,data,status='AVAILABLE',observed_at=null,provenance={source:'CLIENT360'})=>{if(data&&Object.keys(data).length)sources.push({source_type,source_id,source_version:String(data.version||data.updatedAt||'current'),status,observed_at,data,provenance});};
  push('CLIENT_INTAKE','client360-intake',sections.personal||data?.overview||{});
  push('DIETARY_PREFERENCES','client360-nutrition',sections.nutrition||{});
  push('ALLERGIES','client360-allergies',sections.allergiesFamilyHistory||{});
  push('MEDICAL_HISTORY','client360-medical-history',sections.medicalHistory||{});
  push('MEDICATIONS','client360-medications',sections.medicationsSupplements||{});
  push('LIFESTYLE','client360-lifestyle',{...(sections.lifestyle||{}),...(sections.sleepStress||{}),...(sections.activityHydration||{})});
  const latest=measurements?.latest||{};if(Object.keys(latest).length){const byType=type=>latest[type]?.value;push('MEASUREMENT','client360-measurements',{height_cm:byType('HEIGHT_CM'),weight_kg:byType('WEIGHT_KG'),waist_cm:byType('WAIST_CM'),hip_cm:byType('HIP_CM')},'AVAILABLE',Object.values(latest)[0]?.measured_at);}
  (biomarkers||[]).filter(item=>item.reviewStatus==='CONFIRMED'||item.review_status==='CONFIRMED').forEach(item=>push('BIOMARKER',String(item.id||item.canonicalBiomarkerId),{canonical_biomarker_id:item.canonicalBiomarkerId||item.canonical_biomarker_id,value:item.value,unit:item.unit,source_report_reference:item.documentId||item.sourceReportReference||'TRANSIENT_ANALYSIS'},'CONFIRMED',item.observationDate,{source:'CONFIRMED_CLIENT_BIOMARKER'}));
  return sources;
}

function Readiness({value}){const checklist=value?.checklist||{};return <section className="rounded-[24px] border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-blue-700">Diet Plan readiness</p><h3 className="mt-1 text-xl font-semibold">{label(value?.outcome||'NOT_STARTED')}</h3></div><span className={`rounded-full px-3 py-1 text-xs font-bold ${value?.outcome==='READY'?'bg-emerald-100 text-emerald-800':value?.outcome==='BLOCKED'?'bg-red-100 text-red-800':'bg-amber-100 text-amber-800'}`}>{value?.outcome||'NOT_STARTED'}</span></div><p className="mt-2 text-xs leading-5 text-slate-500">Operational readiness supports professional workflow. It is not a clinical safety guarantee.</p><ul className="mt-5 space-y-2">{Object.entries(checklist).map(([key,ready])=><li key={key} className="flex items-center gap-2 text-sm">{ready?<CheckCircle2 size={17} className="text-emerald-600"/>:<CircleAlert size={17} className="text-amber-600"/>}<span>{label(key)}</span></li>)}</ul>{value?.outstanding_information?.length>0&&<div className="mt-5 rounded-xl bg-amber-50 p-3"><p className="text-xs font-bold text-amber-900">Outstanding information</p><p className="mt-1 text-sm text-amber-800">{value.outstanding_information.map(label).join(' · ')}</p></div>}</section>}

export default function ExternalNutritionAssessment({clientId,data,measurements,biomarkers,onError}){
  const [state,setState]=useState({loading:true,value:null});const [form,setForm]=useState(EMPTY);const [busy,setBusy]=useState('');const [notice,setNotice]=useState('');
  const sources=useMemo(()=>buildSources(data,measurements,biomarkers),[data,measurements,biomarkers]);
  const load=async()=>{setState(current=>({...current,loading:true}));try{const value=await getNutritionAssessment(clientId);setState({loading:false,value});setForm({...EMPTY,...(value.assessment_data||{})});}catch(error){setState({loading:false,value:null});onError(error.message);}};
  useEffect(()=>{void load()},[clientId]);
  const set=(key,value)=>setForm(current=>({...current,[key]:value}));
  const save=async action=>{setBusy(action);setNotice('');try{await saveNutritionAssessment(clientId,{expected_version:state.value?.current_version??state.value?.version??0,action,profile:form,sources,clinical_safety_findings:[]});await load();setNotice(action==='SUBMIT'?'Assessment submitted for review.':'Draft saved.');}catch(error){onError(error.message)}finally{setBusy('')}};
  const transition=async action=>{setBusy(action);try{const value=await transitionNutritionAssessment(state.value.id,{action,expected_version:state.value.current_version??state.value.version,notes:null});await load();setNotice(action==='MARK_REVIEWED'?'Assessment reviewed. Diet Plan readiness recalculated.':'Assessment workflow updated.');return value;}catch(error){onError(error.message)}finally{setBusy('')}};
  if(state.loading)return <section aria-live="polite" className="rounded-2xl bg-white p-8 text-center text-sm text-slate-500">Loading Nutrition Assessment…</section>;
  const status=state.value?.status||'NOT_STARTED';
  return <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_340px]"><div className="space-y-5"><section className="rounded-[24px] border border-slate-200 bg-white p-5 shadow-sm sm:p-6"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2 text-blue-700"><ClipboardList size={18}/><p className="text-xs font-bold uppercase tracking-[0.16em]">Nutrition Assessment</p></div><h2 className="mt-2 text-2xl font-semibold tracking-tight">Diet planning context</h2><p className="mt-1 text-sm text-slate-500">Review source-backed client context, record the assessment, then complete consultant review.</p></div><span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold text-slate-700">{label(status)}</span></div>{notice&&<p role="status" className="mt-4 rounded-xl bg-emerald-50 p-3 text-sm font-semibold text-emerald-800">{notice}</p>}<div className="mt-6 grid gap-4 sm:grid-cols-2"><Field label="Dietary preference"><select value={form.dietary_preference||''} onChange={event=>set('dietary_preference',event.target.value||null)} className={fieldClass}><option value="">Not provided</option>{['VEGETARIAN','EGG','NON_VEGETARIAN','VEGAN'].map(value=><option key={value} value={value}>{label(value)}</option>)}</select></Field><ListField label="Allergies and intolerances" value={form.allergies_intolerances} onChange={value=>set('allergies_intolerances',value)}/><ListField label="Food restrictions" value={form.food_restrictions} onChange={value=>set('food_restrictions',value)}/><Field label="Meal timing and frequency"><textarea rows="3" value={form.meal_timing_frequency||''} onChange={event=>set('meal_timing_frequency',event.target.value)} className={fieldClass}/></Field><Field wide label="Typical dietary intake"><textarea rows="4" value={form.typical_dietary_intake||''} onChange={event=>set('typical_dietary_intake',event.target.value)} className={fieldClass}/></Field><Field label="Appetite and eating patterns"><textarea rows="3" value={form.appetite_eating_patterns||''} onChange={event=>set('appetite_eating_patterns',event.target.value)} className={fieldClass}/></Field><Field label="Water intake"><input value={form.water_intake||''} onChange={event=>set('water_intake',event.target.value)} className={fieldClass}/></Field><Field wide label="Food dislikes and preferences"><textarea rows="3" value={form.food_dislikes_preferences||''} onChange={event=>set('food_dislikes_preferences',event.target.value)} className={fieldClass}/></Field><ListField label="Nutrition-related medical conditions" value={form.nutrition_medical_conditions} onChange={value=>set('nutrition_medical_conditions',value)}/><ListField label="Relevant medications" value={form.relevant_medications} onChange={value=>set('relevant_medications',value)}/><ListField label="Relevant supplements" value={form.relevant_supplements} onChange={value=>set('relevant_supplements',value)}/><ListField label="Weight-management goals" value={form.weight_management_goals} onChange={value=>set('weight_management_goals',value)}/><ListField label="Recovery and disease-management goals" value={form.recovery_disease_management_goals} onChange={value=>set('recovery_disease_management_goals',value)}/><Field wide label="Consultant notes"><textarea rows="4" value={form.consultant_notes||''} onChange={event=>set('consultant_notes',event.target.value)} className={fieldClass}/></Field></div><div className="mt-6 flex flex-wrap gap-3"><button disabled={Boolean(busy)||!['NOT_STARTED','DRAFT','CHANGES_REQUESTED'].includes(status)} onClick={()=>save('SAVE_DRAFT')} className="min-h-11 rounded-xl border border-slate-300 px-4 text-sm font-semibold disabled:opacity-40">{busy==='SAVE_DRAFT'?'Saving…':'Save draft'}</button><button disabled={Boolean(busy)||!['NOT_STARTED','DRAFT','CHANGES_REQUESTED'].includes(status)} onClick={()=>save('SUBMIT')} className="min-h-11 rounded-xl bg-slate-950 px-4 text-sm font-semibold text-white disabled:opacity-40">{busy==='SUBMIT'?'Submitting…':'Submit for review'}</button>{status==='SUBMITTED'&&<button disabled={Boolean(busy)} onClick={()=>transition('START_REVIEW')} className="min-h-11 rounded-xl bg-blue-700 px-4 text-sm font-semibold text-white">Start review</button>}{['SUBMITTED','IN_REVIEW'].includes(status)&&<><button disabled={Boolean(busy)} onClick={()=>transition('MARK_REVIEWED')} className="min-h-11 rounded-xl bg-emerald-700 px-4 text-sm font-semibold text-white">Mark reviewed</button><button disabled={Boolean(busy)} onClick={()=>transition('REQUEST_CHANGES')} className="min-h-11 rounded-xl border border-amber-300 px-4 text-sm font-semibold text-amber-900">Request changes</button></>}</div></section><SourceSummary data={data} measurements={measurements} biomarkers={biomarkers}/>{state.value?.history?.length>0&&<section className="rounded-[24px] border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><History size={18}/><h3 className="font-semibold">Assessment history</h3></div><ol className="mt-4 space-y-3">{state.value.history.map((item,index)=><li key={`${item.created_at}-${index}`} className="rounded-xl bg-slate-50 p-3 text-sm"><strong>{label(item.event_type)}</strong><span className="text-slate-500"> · {label(item.from_status||'new')} → {label(item.to_status)} · version {item.assessment_version}</span><time className="mt-1 block text-xs text-slate-400">{new Date(item.created_at).toLocaleString()}</time></li>)}</ol></section>}</div><Readiness value={state.value?.readiness}/></div>;
}

function Field({label:caption,wide=false,children}){return <label className={`block text-sm font-semibold text-slate-800 ${wide?'sm:col-span-2':''}`}>{caption}{children}</label>}
function ListField({label:caption,value,onChange}){return <Field label={`${caption} (comma separated)`}><input value={list(value).join(', ')} onChange={event=>onChange(split(event.target.value))} className={fieldClass}/></Field>}
function SourceSummary({data,measurements,biomarkers}){const rows=[['Current weight',measurements?.latest?.WEIGHT_KG?.value!=null?`${measurements.latest.WEIGHT_KG.value} kg`:'Not provided'],['BMI',measurements?.calculations?.bmi?.value??data?.derived?.bmi?.value??'Not provided'],['Medical conditions',list(data?.sections?.medicalHistory?.conditions).join(', ')||'Not provided'],['Health goals',list(data?.sections?.goals?.selectedGoals).join(', ')||'Not provided'],['Confirmed biomarkers',String((biomarkers||[]).filter(item=>item.reviewStatus==='CONFIRMED'||item.review_status==='CONFIRMED').length)]];return <section className="rounded-[24px] border border-slate-200 bg-[#f8f7f2] p-5"><p className="text-xs font-bold uppercase tracking-[0.16em] text-slate-500">Existing client information</p><h3 className="mt-1 text-lg font-semibold">Read-only health context</h3><dl className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{rows.map(([caption,value])=><div key={caption} className="rounded-xl bg-white p-3"><dt className="text-xs text-slate-500">{caption}</dt><dd className="mt-1 text-sm font-semibold">{value}</dd></div>)}</dl></section>}
